import React, { useEffect, useState } from 'react';
import { AnalysisData, SessionConfig } from '../types';
import { generateAnalysis } from '../services/gemini';
import { Message } from '../types';
import { RefreshCw, Sparkles, Target, RotateCcw, Download, Radar as RadarIcon, CheckCircle2, AlertTriangle, FileText } from 'lucide-react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer } from 'recharts';

export const ReportView: React.FC<{
  config: SessionConfig;
  transcript: Message[];
  aiDeclaration: string;
  onRestart: () => void;
}> = ({ config, transcript, aiDeclaration, onRestart }) => {
  const [analysis, setAnalysis] = useState<AnalysisData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const runAnalysis = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await generateAnalysis(transcript, config.topic, aiDeclaration);
      setAnalysis(result);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { runAnalysis(); }, []);

  const getChartData = () => {
    if (!analysis) return [];
    return [
      { subject: 'Raisonnement', A: analysis.reasoningScore, fullMark: 100 },
      { subject: 'Clarté', A: analysis.clarityScore, fullMark: 100 },
      { subject: 'Scepticisme', A: analysis.skepticismScore, fullMark: 100 },
      { subject: 'Processus', A: analysis.processScore, fullMark: 100 },
      { subject: 'Réflexion', A: analysis.reflectionScore, fullMark: 100 },
    ];
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center h-screen bg-slate-50">
      <RefreshCw className="animate-spin text-indigo-600 mb-6" size={48} />
      <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Analyse du Processus Argos...</h2>
      <p className="text-slate-400 text-xs font-bold mt-2 uppercase">Génération par Gemini 3 Pro (Thinking)</p>
    </div>
  );

  if (error || !analysis) return (
    <div className="flex flex-col items-center justify-center h-screen p-8 text-center space-y-6">
      <h2 className="text-2xl font-black text-slate-900 uppercase">Erreur d'Audit</h2>
      <button onClick={runAnalysis} className="flex items-center gap-2 px-8 py-3 bg-indigo-600 text-white rounded-xl font-black text-xs uppercase"><RotateCcw size={18} /> Réessayer</button>
    </div>
  );

  return (
    <div className="min-h-screen bg-white p-4 sm:p-12 print:p-0">
      <div className="max-w-5xl mx-auto space-y-12 animate-in fade-in duration-700 print:space-y-8">

        {/* HEADER */}
        <header className="bg-slate-900 text-white p-10 rounded-[2.5rem] shadow-xl flex flex-col md:flex-row justify-between items-start gap-8 print:bg-slate-50 print:text-slate-900 print:rounded-xl print:shadow-none print:border-2 print:border-slate-200 print:p-8">
          <div className="space-y-4">
            <div className="flex items-center gap-4 text-indigo-400 print:text-indigo-600">
              <Sparkles size={24} />
              <p className="text-[10px] font-black uppercase tracking-[0.6em]">Trace d'Apprentissage DES</p>
            </div>
            <h1 className="text-5xl font-black tracking-tighter uppercase leading-none print:text-3xl">{config.studentName}</h1>
            <p className="text-slate-400 text-lg font-bold uppercase print:text-slate-600">{config.topic}</p>
          </div>
          <div className="flex flex-col sm:flex-row md:flex-col gap-3 no-print">
            <button 
              onClick={() => window.print()} 
              className="flex items-center justify-center gap-3 bg-white text-slate-900 px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-50 transition-all shadow-lg active:scale-95"
            >
              <Download size={16} /> Enregistrer en PDF
            </button>
            <button 
              onClick={onRestart} 
              className="flex items-center justify-center gap-3 bg-slate-800 text-slate-400 px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:text-white transition-all active:scale-95"
            >
              <RotateCcw size={16} /> Nouvelle Session
            </button>
          </div>
        </header>

        {/* SECTION GRAPHIQUE ET RÉSUMÉ */}
        <section className="grid grid-cols-1 lg:grid-cols-12 gap-8 print:block print:space-y-8">
          {/* Synthèse */}
          <div className="lg:col-span-7 space-y-6">
            <div className="bg-slate-50 p-8 rounded-[2rem] border border-slate-200 print:p-6 print:rounded-xl print:border-slate-300">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                <FileText size={14} /> Synthèse du Processus
              </h3>
              <p className="text-sm text-slate-800 leading-relaxed font-medium italic">
                {analysis.summary}
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="bg-emerald-50 p-6 rounded-2xl border border-emerald-100 print:border-emerald-300">
                <h4 className="text-[9px] font-black text-emerald-900 uppercase tracking-widest mb-3 flex items-center gap-2">
                  <CheckCircle2 size={14} /> Forces Clés
                </h4>
                <ul className="space-y-2">
                  {analysis.keyStrengths.map((s, i) => (
                    <li key={i} className="text-[11px] text-emerald-800 font-bold">• {s}</li>
                  ))}
                </ul>
              </div>
              <div className="bg-rose-50 p-6 rounded-2xl border border-rose-100 print:border-rose-300">
                <h4 className="text-[9px] font-black text-rose-900 uppercase tracking-widest mb-3 flex items-center gap-2">
                  <AlertTriangle size={14} /> Vigilances / Faiblesses
                </h4>
                <ul className="space-y-2">
                  {analysis.weaknesses.map((w, i) => (
                    <li key={i} className="text-[11px] text-rose-800 font-bold">• {w}</li>
                  ))}
                </ul>
              </div>
            </div>
          </div>

          {/* Graphique Radar */}
          <div className="lg:col-span-5 bg-white border-2 border-slate-100 rounded-[2.5rem] p-6 shadow-sm flex flex-col items-center justify-center print:border-slate-300 print:rounded-xl print:mt-8">
             <div className="flex items-center gap-2 mb-4">
                <RadarIcon className="text-indigo-600" size={16} />
                <h3 className="text-[10px] font-black text-slate-900 uppercase tracking-widest">Dimensions Cognitives</h3>
             </div>
             <div className="w-full h-[320px]">
                <ResponsiveContainer width="100%" height="100%">
                  <RadarChart cx="50%" cy="50%" outerRadius="80%" data={getChartData()}>
                    <PolarGrid stroke="#e2e8f0" />
                    <PolarAngleAxis dataKey="subject" tick={{ fontSize: 10, fontWeight: 700, fill: '#64748b' }} />
                    <PolarRadiusAxis angle={30} domain={[0, 100]} tick={{ fontSize: 8 }} />
                    <Radar
                      name="Apprenant"
                      dataKey="A"
                      stroke="#4f46e5"
                      fill="#4f46e5"
                      fillOpacity={0.6}
                    />
                  </RadarChart>
                </ResponsiveContainer>
             </div>
             <div className="mt-4 flex flex-wrap justify-center gap-4 border-t border-slate-50 pt-4 w-full">
                <div className="flex items-center gap-1.5">
                  <div className="w-2 h-2 rounded-full bg-slate-200"></div>
                  <span className="text-[8px] font-black uppercase text-slate-400">0-40 Amorcé</span>
                </div>
                <div className="flex items-center gap-1.5">
                  <div className="w-2 h-2 rounded-full bg-indigo-300"></div>
                  <span className="text-[8px] font-black uppercase text-slate-400">41-70 Stabilisé</span>
                </div>
                <div className="flex items-center gap-1.5">
                  <div className="w-2 h-2 rounded-full bg-indigo-600"></div>
                  <span className="text-[8px] font-black uppercase text-slate-400">71-100 Expert</span>
                </div>
             </div>
          </div>
        </section>

        {/* TRANSCRIPT / PROMPTOGRAPHIE */}
        <section className="pt-12 border-t border-slate-100 print:pt-8 print:border-slate-300">
          <div className="flex items-center gap-3 mb-8 print:mb-4">
            <Target className="text-slate-900" size={24} />
            <h3 className="text-xs font-black text-slate-900 uppercase tracking-widest">Dialogue d'Origine (Promptographie)</h3>
          </div>
          <div className="space-y-4 max-h-96 overflow-y-auto pr-4 scrollbar-hide opacity-60 hover:opacity-100 transition-opacity print:max-h-none print:overflow-visible print:opacity-100 print:pr-0">
            {transcript.filter(m => !m.text.includes("Bonjour Argos")).map((m, i) => (
              <div key={i} className={`p-4 rounded-xl text-xs print:text-[10pt] print:break-inside-avoid ${m.role === 'user' ? 'bg-slate-100 border-l-4 border-slate-900' : 'bg-indigo-50 border-l-4 border-indigo-600'}`}>
                <span className="font-black uppercase text-[9px] print:text-[8pt] block mb-1">{m.role === 'user' ? 'Étudiant·e' : 'Argos'}</span>
                <div className="prose prose-sm max-w-none text-slate-800">
                   {m.text}
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* FOOTER PDF */}
        <footer className="pt-20 border-t border-slate-100 text-center opacity-30 print:opacity-100 print:pt-10">
           <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.4em] print:text-slate-600">Document Certifié par le Système Argos Socratique • Protocole Phased V3</p>
        </footer>
      </div>
    </div>
  );
};

export enum AppMode {
  LOGIN = 'LOGIN',
  SETUP = 'SETUP',
  CHAT = 'CHAT',
  REPORT = 'REPORT'
}

export enum SocraticMode {
  TUTOR = 'TUTOR',
  CRITIC = 'CRITIC'
}

export enum SocraticStrategy {
  CLARIFICATION = 'clarification',
  TEST_NECESSITE = 'test_necessite',
  CONTRE_EXEMPLE = 'contre_exemple',
  PREDICTION = 'prediction',
  FALSIFIABILITE = 'falsifiabilite',
  MECANISME_CAUSAL = 'mecanisme_causal',
  CHANGEMENT_CADRE = 'changement_cadre',
  COMPRESSION = 'compression',
  CONCESSION_CONTROLEE = 'concession_controlee'
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
  strategy?: SocraticStrategy;
  phase?: number;
}

export interface SessionConfig {
  studentName: string;
  topic: string;
  mode: SocraticMode;
}

export interface AnalysisData {
  summary: string;
  reasoningScore: number;
  clarityScore: number;
  skepticismScore: number;
  processScore: number;
  reflectionScore: number;
  keyStrengths: string[];
  weaknesses: string[];
  transcript: Message[];
  aiDeclaration: string;
}

export const PROTOCOL_PHASES = [
  { id: 0, label: "Ciblage", desc: "Identification de l'intention et de l'objet de recherche." },
  { id: 1, label: "Clarification", desc: "Définition rigoureuse des termes et des concepts utilisés." },
  { id: 2, label: "Mécanisme", desc: "Exploration du 'Comment' : les relations de cause à effet." },
  { id: 3, label: "Vérification", desc: "Recherche de preuves, de protocoles et de critères de vérité." },
  { id: 4, label: "Stress-test", desc: "Confrontation à des contre-exemples et limites du modèle." }
];

import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_CHAT = "gemini-3-flash-preview";
const MODEL_ANALYSIS = "gemini-3-pro-preview";
const TUTOR_NAME = "ARGOS";

const buildCommonSystem = (topic: string) => {
  return `
IDENTITÉ :
- Tu es ${TUTOR_NAME}.
- Tu conduis un "Dialogue Évaluatif Socratique" (DES).
- Tu n’es pas un coach. Tu es un dispositif de guidage critique.
- Sujet : "${topic}".

LANGUE : Français uniquement. Tutoiement obligatoire. Écriture inclusive au point médian.

TON : Direct, sobre, sceptique. Interdits : compliments, flatterie, encouragements creux.
Autorisé : reconnaissance minimale de la charge cognitive (ex: "Difficile est normal ici.").

CONTRÔLE : Une seule question par message. Pas de corrigé. Longueur : 70-140 mots.

ANTI-GAMING : Refuse le "ça dépend" sans critère ou le "c'est logique".

PHASAGE DU PROTOCOLE (Phased V3) :
Phase 0: Ciblage (Pourquoi cette recherche ?)
Phase 1: Clarification (De quoi parle-t-on précisément ?)
Phase 2: Mécanisme (Comment cela fonctionne-t-il selon toi ?)
Phase 3: Vérification (Comment tester cette hypothèse ?)
Phase 4: Stress-test (Quels contre-exemples invalident ton idée ?)

CONSIGNE DE TRANSPARENCE :
Lorsque tu changes de phase, annonce-le explicitement à l'étudiant·e.

TRACE OBLIGATOIRE (Fin de message) : 
Chaque message doit se terminer par exactement 3 lignes structurées :
Phase: [Numéro de 0 à 4]
Exigence: [Action attendue]
Contrôle: [Condition d'échec]
`.trim();
};

export const createChatSession = (mode: SocraticMode, topic: string, history: Message[] = []): Chat => {
  const systemInstruction = mode === SocraticMode.TUTOR 
    ? `${buildCommonSystem(topic)}\n\nMODE : DÉFENSE (évaluation du raisonnement). Reformulation neutre + Question unique.`
    : `${buildCommonSystem(topic)}\n\nMODE : AUDIT (vigilance). Propose un texte de 150 mots avec 3 défauts constants.`;

  return ai.chats.create({
    model: MODEL_CHAT,
    config: {
      systemInstruction,
      temperature: 0.6,
      thinkingConfig: { thinkingBudget: 2048 }
    },
    history: history.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }))
  });
};

export const sendMessage = async (chat: Chat, message: string) => {
  const response = await chat.sendMessage({ message });
  return { text: response.text || "Erreur de réponse." };
};

export const generateAnalysis = async (
  transcript: Message[],
  topic: string,
  aiDeclaration: string
): Promise<AnalysisData> => {
  const transcriptText = transcript.map(m => `[${m.role === "user" ? "Étudiant·e" : TUTOR_NAME}]: ${m.text}`).join("\n");

  const prompt = `
Analyse le dialogue suivant sur "${topic}". Produis un rapport JSON de processus.
Déclaration IA : "${aiDeclaration}"
Transcription :
${transcriptText}

SCORING (0-100) : Commence à 40. >40 si protocoles explicités. <40 si flou persistant.
`.trim();

  const response = await ai.models.generateContent({
    model: MODEL_ANALYSIS,
    contents: prompt,
    config: {
      temperature: 0.3,
      thinkingConfig: { thinkingBudget: 4096 },
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: { type: Type.STRING, description: "120-170 mots, commence par les insuffisances." },
          reasoningScore: { type: Type.INTEGER },
          clarityScore: { type: Type.INTEGER },
          skepticismScore: { type: Type.INTEGER },
          processScore: { type: Type.INTEGER },
          reflectionScore: { type: Type.INTEGER },
          keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["summary", "reasoningScore", "clarityScore", "skepticismScore", "processScore", "reflectionScore", "keyStrengths", "weaknesses"]
      } as any
    }
  });

  return { ...JSON.parse(response.text || "{}"), transcript, aiDeclaration };
};

import React, { useState, useEffect, useRef } from 'react';
import { Send, StopCircle, RefreshCw, FileSignature, HelpCircle, Save, Info, ChevronRight } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { Chat } from "@google/genai";
import { Message, SessionConfig, SocraticStrategy, PROTOCOL_PHASES } from '../types';
import { sendMessage } from '../services/gemini';
import { GuideModal } from './GuideModal';

export const ChatView: React.FC<{
  chatInstance: Chat | null;
  config: SessionConfig;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  onFinish: (aiDeclaration: string) => void;
}> = ({ chatInstance, config, messages, setMessages, onFinish }) => {
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showDeclarationModal, setShowDeclarationModal] = useState(false);
  const [showGuide, setShowGuide] = useState(false);
  const [declarationText, setDeclarationText] = useState('');
  const [currentPhase, setCurrentPhase] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const extractPhase = (text: string): number => {
    const match = text.match(/Phase:\s*(\d)/i);
    return match ? parseInt(match[1], 10) : currentPhase;
  };

  const handleExportJSON = () => {
    const data = {
      metadata: {
        student: config.studentName,
        topic: config.topic,
        mode: config.mode,
        date: new Date().toISOString()
      },
      transcript: messages,
      aiDeclaration: declarationText || ""
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Progression_${config.studentName}_${new Date().toLocaleDateString()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleSend = async (initialPrompt?: string) => {
    const text = initialPrompt || inputText;
    if (!text.trim() || !chatInstance || isLoading) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: initialPrompt ? "(Démarrage de session)" : text,
      timestamp: Date.now(),
    };

    if (!initialPrompt) setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);
    setError(null);

    try {
      const res = await sendMessage(chatInstance, text);
      const phase = extractPhase(res.text);
      setCurrentPhase(phase);

      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: res.text,
        timestamp: Date.now(),
        phase
      };
      setMessages(prev => [...prev, aiMsg]);
    } catch (e: any) {
      setError("Erreur de communication avec Argos.");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (messages.length === 0 && chatInstance) {
      handleSend(`Bonjour Argos, je suis ${config.studentName}. Lance la session sur : ${config.topic}.`);
    } else if (messages.length > 0) {
      const lastModelMsg = [...messages].reverse().find(m => m.role === 'model');
      if (lastModelMsg?.phase !== undefined) setCurrentPhase(lastModelMsg.phase);
    }
  }, [chatInstance]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {showGuide && <GuideModal onClose={() => setShowGuide(false)} />}

      {showDeclarationModal && (
        <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl max-w-xl w-full p-8 animate-in fade-in zoom-in duration-300">
            <h2 className="text-xl font-black flex items-center gap-3 mb-6 uppercase text-slate-900">
              <FileSignature className="text-indigo-600" /> Journal d'Usage IA
            </h2>
            <textarea 
              value={declarationText} 
              onChange={(e) => setDeclarationText(e.target.value)} 
              placeholder="Comment as-tu utilisé l'IA pour tes recherches ?" 
              className="w-full h-32 p-4 bg-slate-50 border border-slate-200 rounded-xl mb-6 outline-none text-sm" 
            />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowDeclarationModal(false)} className="px-5 text-[10px] font-black uppercase text-slate-400">Retour</button>
              <button onClick={() => onFinish(declarationText || "Aucun usage déclaré.")} className="px-6 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest">Générer la trace</button>
            </div>
          </div>
        </div>
      )}

      {/* PROGRESS TRACKER */}
      <div className="bg-white border-b border-slate-100 px-6 py-2 flex items-center justify-between overflow-x-auto scrollbar-hide no-print">
        <div className="flex items-center gap-2 min-w-max">
          {PROTOCOL_PHASES.map((p, i) => (
            <div key={p.id} className="flex items-center gap-2">
               <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full transition-all duration-500 ${currentPhase === p.id ? 'bg-indigo-600 text-white shadow-md' : currentPhase > p.id ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-50 text-slate-300'}`}>
                  <span className="text-[9px] font-black uppercase tracking-tighter">{i}. {p.label}</span>
                  {currentPhase > p.id && <Info size={10} />}
               </div>
               {i < PROTOCOL_PHASES.length - 1 && <ChevronRight size={12} className="text-slate-200" />}
            </div>
          ))}
        </div>
      </div>

      <header className="bg-white border-b px-6 py-4 flex justify-between items-center shrink-0 shadow-sm z-10 no-print">
        <div className="overflow-hidden flex items-center gap-4">
          <div className="hidden sm:block">
            <h2 className="text-sm font-black text-slate-900 uppercase truncate">{config.topic}</h2>
            <p className="text-[9px] text-slate-400 font-bold tracking-widest">PHASE {currentPhase} : {PROTOCOL_PHASES[currentPhase]?.label.toUpperCase()}</p>
          </div>
          <button 
            onClick={handleExportJSON}
            title="Sauvegarder pour reprendre plus tard"
            className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all flex items-center gap-2 group"
          >
            <Save size={18} />
            <span className="text-[9px] font-black uppercase tracking-widest hidden md:inline">Sauvegarder</span>
          </button>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setShowGuide(true)} className="p-2 text-slate-300 hover:text-slate-600 transition-colors"><HelpCircle size={20} /></button>
          <button onClick={() => setShowDeclarationModal(true)} className="flex items-center gap-2 px-4 py-2 bg-rose-600 text-white rounded-xl text-[10px] font-black tracking-widest uppercase hover:bg-rose-700 transition-colors shadow-lg shadow-rose-100"><StopCircle size={14} /> Terminer</button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-6 scrollbar-hide">
        {messages.filter(m => !m.text.includes("Bonjour Argos")).map((msg) => (
          <div key={msg.id} className={`flex w-full animate-in fade-in slide-in-from-bottom-2 duration-300 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[88%] sm:max-w-[75%] rounded-[1.8rem] px-6 py-5 shadow-md border transition-all ${
              msg.role === 'user' 
                ? 'bg-slate-900 text-white border-slate-800 rounded-tr-none' 
                : 'bg-white text-slate-800 border-slate-200 rounded-tl-none'
            }`}>
              <div className={`prose prose-sm max-w-none font-medium leading-relaxed ${
                msg.role === 'user' ? 'prose-invert prose-p:text-white prose-p:font-semibold' : 'prose-slate'
              }`}>
                <ReactMarkdown>{msg.text}</ReactMarkdown>
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-indigo-600 text-white px-5 py-3 rounded-2xl rounded-tl-none flex items-center gap-3 animate-pulse shadow-lg shadow-indigo-200">
              <RefreshCw className="animate-spin" size={14} />
