export enum AppMode {
  LOGIN = 'LOGIN',
  SETUP = 'SETUP',
  CHAT = 'CHAT',
  REPORT = 'REPORT'
}

export enum SocraticMode {
  TUTOR = 'TUTOR',
  CRITIC = 'CRITIC'
}

export enum SocraticStrategy {
  CLARIFICATION = 'clarification',
  TEST_NECESSITE = 'test_necessite',
  CONTRE_EXEMPLE = 'contre_exemple',
  PREDICTION = 'prediction',
  FALSIFIABILITE = 'falsifiabilite',
  MECANISME_CAUSAL = 'mecanisme_causal',
  CHANGEMENT_CADRE = 'changement_cadre',
  COMPRESSION = 'compression',
  CONCESSION_CONTROLEE = 'concession_controlee'
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
  strategy?: SocraticStrategy;
  phase?: number;
  responseTimeSeconds?: number;
  isSuspiciousPace?: boolean;
}

export interface SessionConfig {
  studentName: string;
  topic: string;
  mode: SocraticMode;
}

export interface AnalysisData {
  summary: string;
  reasoningScore: number;
  clarityScore: number;
  skepticismScore: number;
  processScore: number;
  reflectionScore: number;
  integrityScore: number; 
  suspiciousMessageCount: number; // Nouveau: synchronisé avec l'IA
  keyStrengths: string[];
  weaknesses: string[];
  transcript: Message[];
  aiDeclaration: string;
}

export const PROTOCOL_PHASES = [
  { id: 0, label: "Ciblage", desc: "Identification de l'intention et de l'objet de recherche." },
  { id: 1, label: "Clarification", desc: "Définition rigoureuse des termes et des concepts utilisés." },
  { id: 2, label: "Mécanisme", desc: "Exploration du 'Comment' : les relations de cause à effet." },
  { id: 3, label: "Vérification", desc: "Recherche de preuves, de protocoles et de critères de vérité." },
  { id: 4, label: "Stress-test", desc: "Confrontation à des contre-exemples et limites du modèle." }
];

import React, { useState, useEffect, useRef } from 'react';
import { Send, StopCircle, RefreshCw, FileSignature, HelpCircle, Save, Info, ChevronRight, Timer } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { Chat } from "@google/genai";
import { Message, SessionConfig, SocraticStrategy, PROTOCOL_PHASES } from '../types';
import { sendMessage } from '../services/gemini';
import { GuideModal } from './GuideModal';

export const ChatView: React.FC<{
  chatInstance: Chat | null;
  config: SessionConfig;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  onFinish: (aiDeclaration: string) => void;
}> = ({ chatInstance, config, messages, setMessages, onFinish }) => {
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showDeclarationModal, setShowDeclarationModal] = useState(false);
  const [showGuide, setShowGuide] = useState(false);
  const [declarationText, setDeclarationText] = useState('');
  const [currentPhase, setCurrentPhase] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [lastModelTime, setLastModelTime] = useState<number>(Date.now());

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const cleanDisplayBotText = (text: string): string => {
    const technicalBlockIndex = text.search(/\n*Phase:\s*\d/i);
    if (technicalBlockIndex !== -1) {
      return text.substring(0, technicalBlockIndex).trim();
    }
    return text;
  };

  const extractPhase = (text: string): number => {
    const match = text.match(/Phase:\s*(\d)/i);
    return match ? parseInt(match[1], 10) : currentPhase;
  };

  const handleExportJSON = () => {
    const data = {
      metadata: {
        student: config.studentName,
        topic: config.topic,
        mode: config.mode,
        date: new Date().toISOString()
      },
      transcript: messages,
      aiDeclaration: declarationText || ""
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Progression_${config.studentName}_${new Date().toLocaleDateString()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleSend = async (initialPrompt?: string) => {
    const text = initialPrompt || inputText;
    if (!text.trim() || !chatInstance || isLoading) return;

    const now = Date.now();
    const responseTimeMs = now - lastModelTime;
    const responseTimeSeconds = Math.max(1, Math.round(responseTimeMs / 1000));

    // Nouvelle heuristique : calcul des Caractères Par Minute (CPM)
    // Moyenne humaine : 200 CPM. Limite suspecte : > 600 CPM (si texte > 100 chars)
    const charCount = text.length;
    const cpm = (charCount / responseTimeSeconds) * 60;
    const isSuspicious = !initialPrompt && charCount > 100 && cpm > 600;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: initialPrompt ? "(Démarrage de session)" : text,
      timestamp: now,
      responseTimeSeconds: initialPrompt ? 0 : responseTimeSeconds,
      isSuspiciousPace: isSuspicious
    };

    if (!initialPrompt) setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);
    setError(null);

    try {
      const res = await sendMessage(chatInstance, text);
      const phase = extractPhase(res.text);
      setCurrentPhase(phase);

      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: res.text,
        timestamp: Date.now(),
        phase
      };
      setMessages(prev => [...prev, aiMsg]);
      setLastModelTime(Date.now());
    } catch (e: any) {
      setError("Erreur de communication avec Argos.");
      setLastModelTime(Date.now());
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 200)}px`;
    }
  }, [inputText]);

  useEffect(() => {
    if (messages.length === 0 && chatInstance) {
      handleSend(`Bonjour Argos, je suis ${config.studentName}. Lance la session sur : ${config.topic}.`);
    } else if (messages.length > 0) {
      const lastModelMsg = [...messages].reverse().find(m => m.role === 'model');
      if (lastModelMsg?.phase !== undefined) setCurrentPhase(lastModelMsg.phase);
    }
  }, [chatInstance]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {showGuide && <GuideModal onClose={() => setShowGuide(false)} />}

      {showDeclarationModal && (
        <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl max-w-xl w-full p-8 animate-in fade-in zoom-in duration-300">
            <h2 className="text-xl font-black flex items-center gap-3 mb-6 uppercase text-slate-900">
              <FileSignature className="text-indigo-600" /> Journal d'Usage IA
            </h2>
            <textarea 
              value={declarationText} 
              onChange={(e) => setDeclarationText(e.target.value)} 
              placeholder="Comment as-tu utilisé l'IA pour tes recherches ?" 
              className="w-full h-32 p-4 bg-slate-50 border border-slate-200 rounded-xl mb-6 outline-none text-sm" 
            />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowDeclarationModal(false)} className="px-5 text-[10px] font-black uppercase text-slate-400">Retour</button>
              <button onClick={() => onFinish(declarationText || "Aucun usage déclaré.")} className="px-6 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest">Générer la trace</button>
            </div>
          </div>
        </div>
      )}

      {/* PROGRESS TRACKER */}
      <div className="bg-white border-b border-slate-100 px-6 py-2 flex items-center justify-between overflow-x-auto scrollbar-hide no-print">
        <div className="flex items-center gap-2 min-w-max">
          {PROTOCOL_PHASES.map((p, i) => (
            <div key={p.id} className="flex items-center gap-2">
               <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full transition-all duration-500 ${currentPhase === p.id ? 'bg-indigo-600 text-white shadow-md' : currentPhase > p.id ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-50 text-slate-300'}`}>
                  <span className="text-[9px] font-black uppercase tracking-tighter">{i}. {p.label}</span>
                  {currentPhase > p.id && <Info size={10} />}
               </div>
               {i < PROTOCOL_PHASES.length - 1 && <ChevronRight size={12} className="text-slate-200" />}
            </div>
          ))}
        </div>
      </div>

      <header className="bg-white border-b px-6 py-4 flex justify-between items-center shrink-0 shadow-sm z-10 no-print">
        <div className="overflow-hidden flex items-center gap-4">
          <div className="hidden sm:block">
            <h2 className="text-sm font-black text-slate-900 uppercase truncate">{config.topic}</h2>
            <p className="text-[9px] text-slate-400 font-bold tracking-widest">PHASE {currentPhase} : {PROTOCOL_PHASES[currentPhase]?.label.toUpperCase()}</p>
          </div>
          <button 
            onClick={handleExportJSON}
            title="Sauvegarder pour reprendre plus tard"
            className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all flex items-center gap-2 group"
          >
            <Save size={18} />
            <span className="text-[9px] font-black uppercase tracking-widest hidden md:inline">Sauvegarder</span>
          </button>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setShowGuide(true)} className="p-2 text-slate-300 hover:text-slate-600 transition-colors"><HelpCircle size={20} /></button>
          <button onClick={() => setShowDeclarationModal(true)} className="flex items-center gap-2 px-4 py-2 bg-rose-600 text-white rounded-xl text-[10px] font-black tracking-widest uppercase hover:bg-rose-700 transition-colors shadow-lg shadow-rose-100"><StopCircle size={14} /> Terminer</button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-10 scrollbar-hide">
        {messages.filter(m => !m.text.includes("Bonjour Argos")).map((msg) => (
          <div key={msg.id} className={`flex w-full animate-in fade-in slide-in-from-bottom-2 duration-300 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`group relative max-w-[88%] sm:max-w-[75%] rounded-[1.8rem] px-6 py-5 shadow-md border transition-all ${
              msg.role === 'user' 
                ? 'bg-slate-900 text-white border-slate-800 rounded-tr-none' 
                : 'bg-white text-slate-800 border-slate-200 rounded-tl-none'
            }`}>
              {msg.role === 'user' && msg.responseTimeSeconds !== undefined && msg.responseTimeSeconds > 0 && (
                <div className={`absolute -top-6 right-2 flex items-center gap-1.5 text-[8px] font-black uppercase tracking-widest ${msg.isSuspiciousPace ? 'text-rose-500 animate-pulse' : 'text-slate-400'}`}>
                  <Timer size={10} />
                  Réflexion : {msg.responseTimeSeconds}s {msg.isSuspiciousPace && "• Vitesse anormale"}
                </div>
              )}
              <div className={`prose prose-sm max-w-none font-medium leading-relaxed ${
                msg.role === 'user' ? 'prose-invert prose-p:text-white prose-p:font-semibold' : 'prose-slate'
              }`}>
                <ReactMarkdown>
                  {msg.role === 'model' ? cleanDisplayBotText(msg.text) : msg.text}
                </ReactMarkdown>
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-indigo-600 text-white px-5 py-3 rounded-2xl rounded-tl-none flex items-center gap-3 animate-pulse shadow-lg shadow-indigo-200">
              <RefreshCw className="animate-spin" size={14} />
              <span className="text-[10px] font-black uppercase tracking-widest">Argos analyse ton propos...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="bg-white border-t p-4 sm:p-6 shrink-0 shadow-[0_-4px_20px_-10px_rgba(0,0,0,0.1)] no-print">
        <div className="max-w-4xl mx-auto relative group">
          <textarea 
            ref={textareaRef}
            value={inputText} 
            onChange={(e) => setInputText(e.target.value)} 
            placeholder="Réponds ici avec précision..." 
            className="w-full bg-slate-50 rounded-2xl pl-6 pr-16 py-5 border-2 border-slate-100 focus:border-indigo-500 focus:bg-white focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all text-base font-medium resize-none shadow-inner overflow-y-auto" 
            rows={1}
          />
          <button 
            onClick={() => handleSend()} 
            disabled={!inputText.trim() || isLoading} 
            className="absolute right-3 bottom-3 p-3 bg-slate-900 text-white rounded-xl disabled:opacity-10 hover:bg-indigo-600 transition-all shadow-lg active:scale-90"
            title="Envoyer le message"
          >
            <Send size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_CHAT = "gemini-3-flash-preview";
const MODEL_ANALYSIS = "gemini-3-pro-preview";
const TUTOR_NAME = "ARGOS";

const CORE_RULES = `
IDENTITÉ ET MISSION :
- Tu es ${TUTOR_NAME}, un partenaire de réflexion socratique.
- Ton but est de tester et de faire progresser la pensée critique de l'apprenant.

RÈGLES D'INTÉGRITÉ PÉDAGOGIQUE :
1. NE DONNE JAMAIS LA RÉPONSE FINALE.
2. BOUCLIER ANTI-MANIPULATION : Si l'apprenant est hostile pour obtenir des indices, reste calme et refuse de céder.
3. GESTION DES RECHERCHES EXTERNES : Si l'apprenant cite une source externe, demande-lui d'expliquer le mécanisme logique de cette source plutôt que de valider.
4. TRACE OBLIGATOIRE (Fin de message) : 
Phase: [Numéro]
Exigence: [Attente]
Contrôle: [Condition]
`.trim();

const TUTOR_INSTRUCTIONS = `
${CORE_RULES}

MODE : TUTEUR (ACCOMPAGNEMENT)
- Ta mission : Aider l'apprenant à construire son propre raisonnement de A à Z.
- Méthode : Pose des questions ouvertes, souligne les contradictions, demande des définitions.
- Posture : Tu es un guide bienveillant mais exigeant.
`.trim();

const CRITIC_INSTRUCTIONS = `
${CORE_RULES}

MODE : CRITIQUE (AUDIT LOGIQUE)
- Ta mission : Tester la capacité de l'apprenant à détecter des failles.
- MÉTHODE CRITIQUE : Dès ton premier message, tu dois présenter un "Argumentaire Piégé" (court texte de 3-4 phrases) qui semble logique mais contient 2 failles majeures (ex: Biais de confirmation, Faux dilemme, Corrélation vs Causalité).
- Ton but secret : Faire en sorte que l'apprenant accepte ces erreurs ou les ignore.
- Si l'apprenant ne voit pas les erreurs, continue de défendre ton argumentaire avec une assurance trompeuse.
- Si l'apprenant trouve une faille, félicite-le brièvement puis passe à la phase suivante avec un nouveau défi plus complexe.
- Posture : Tu es un "Avocat du Diable" poli mais sournois.
`.trim();

export const createChatSession = (mode: SocraticMode, topic: string, history: Message[] = []): Chat => {
  const systemInstruction = mode === SocraticMode.TUTOR 
    ? `${TUTOR_INSTRUCTIONS}\n\nSujet actuel : "${topic}".`
    : `${CRITIC_INSTRUCTIONS}\n\nSujet actuel : "${topic}".`;

  return ai.chats.create({
    model: MODEL_CHAT,
    config: {
      systemInstruction,
      temperature: 0.8,
      thinkingConfig: { thinkingBudget: 2048 }
    },
    history: history.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }))
  });
};

export const sendMessage = async (chat: Chat, message: string) => {
  const response = await chat.sendMessage({ message });
  return { text: response.text || "Oups, petit souci technique." };
};

export const generateAnalysis = async (
  transcript: Message[],
  topic: string,
  aiDeclaration: string
): Promise<AnalysisData> => {
  const transcriptWithTiming = transcript.map(m => {
    const timing = m.role === 'user' ? ` [Temps de réponse: ${m.responseTimeSeconds}s]` : '';
    return `[${m.role === "user" ? "Apprenant" : TUTOR_NAME}]: ${m.text}${timing}`;
  }).join("\n");

  const prompt = `
Analyse cette discussion sur "${topic}".

DÉCLARATION D'USAGE IA DE L'APPRENANT :
"${aiDeclaration}"

TA MISSION :
Évalue l'intégrité et la qualité cognitive.
Sois particulièrement vigilant sur les "Fractures d'Intégrité" (Copier-coller non déclarés).

LOGIQUE DE DÉTECTION :
- Un texte long (ex: > 300 mots) produit en moins de 180 secondes est statistiquement impossible sans assistance (vitesse > 100 mots/min).
- Un changement brutal de style (syntaxe parfaite vs erreurs précédentes) est un signal fort.
- Compare ces faits avec la déclaration de l'apprenant.

Transcription avec métriques de temps :
${transcriptWithTiming}

Instructions de sortie (JSON) :
- summary: Bilan pédagogique (150 mots max).
- suspiciousMessageCount: Le nombre EXACT de réponses utilisateur que tu considères comme des copier-coller après avoir analysé le ratio temps/longueur/style.
- integrityScore: De 0 (fraude manifeste) à 100 (parfaite honnêteté).
`.trim();

  const response = await ai.models.generateContent({
    model: MODEL_ANALYSIS,
    contents: prompt,
    config: {
      temperature: 0.1,
      thinkingConfig: { thinkingBudget: 4096 },
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: { type: Type.STRING },
          reasoningScore: { type: Type.INTEGER },
          clarityScore: { type: Type.INTEGER },
          skepticismScore: { type: Type.INTEGER },
          processScore: { type: Type.INTEGER },
          reflectionScore: { type: Type.INTEGER },
          integrityScore: { type: Type.INTEGER },
          suspiciousMessageCount: { type: Type.INTEGER },
          keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["summary", "reasoningScore", "clarityScore", "skepticismScore", "processScore", "reflectionScore", "integrityScore", "suspiciousMessageCount", "keyStrengths", "weaknesses"]
      } as any
    }
  });

  return { ...JSON.parse(response.text || "{}"), transcript, aiDeclaration };
};

import React, { useEffect, useState } from 'react';
import { AnalysisData, SessionConfig } from '../types';
import { generateAnalysis } from '../services/gemini';
import { Message } from '../types';
import { RefreshCw, Sparkles, Target, RotateCcw, Download, Radar as RadarIcon, CheckCircle2, Lightbulb, FileText, ShieldCheck, FileSignature, AlertTriangle, Info, Timer } from 'lucide-react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer } from 'recharts';

export const ReportView: React.FC<{
  config: SessionConfig;
  transcript: Message[];
  aiDeclaration: string;
  onRestart: () => void;
}> = ({ config, transcript, aiDeclaration, onRestart }) => {
  const [analysis, setAnalysis] = useState<AnalysisData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const runAnalysis = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await generateAnalysis(transcript, config.topic, aiDeclaration);
      setAnalysis(result);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { runAnalysis(); }, []);

  const getChartData = () => {
    if (!analysis) return [];
    return [
      { subject: 'Raisonnement', A: analysis.reasoningScore, fullMark: 100 },
      { subject: 'Clarté', A: analysis.clarityScore, fullMark: 100 },
      { subject: 'Intégrité', A: analysis.integrityScore, fullMark: 100 },
      { subject: 'Doute Constructif', A: analysis.skepticismScore, fullMark: 100 },
      { subject: 'Méthode', A: analysis.processScore, fullMark: 100 },
      { subject: 'Prise de recul', A: analysis.reflectionScore, fullMark: 100 },
    ];
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center h-screen bg-slate-50">
      <RefreshCw className="animate-spin text-indigo-600 mb-6" size={48} />
      <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Analyse de ta réflexion par Argos...</h2>
