            studentName: json.metadata?.student || "Apprenant·e",
            topic: json.metadata?.topic || "Sujet importé",
            mode: json.metadata?.mode || SocraticMode.TUTOR
          };

          onResume(resumedConfig, json.transcript, json.aiDeclaration || "");
