import React, { useState, useEffect, useRef } from 'react';
import { Send, StopCircle, RefreshCw, FileSignature, HelpCircle, Save, Info, ChevronRight, Timer } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { Chat } from "@google/genai";
import { Message, SessionConfig, SocraticStrategy, PROTOCOL_PHASES } from '../types';
import { sendMessage } from '../services/gemini';
import { GuideModal } from './GuideModal';

export const ChatView: React.FC<{
  chatInstance: Chat | null;
  config: SessionConfig;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  onFinish: (aiDeclaration: string) => void;
}> = ({ chatInstance, config, messages, setMessages, onFinish }) => {
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showDeclarationModal, setShowDeclarationModal] = useState(false);
  const [showGuide, setShowGuide] = useState(false);
  const [declarationText, setDeclarationText] = useState('');
  const [currentPhase, setCurrentPhase] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [lastModelTime, setLastModelTime] = useState<number>(Date.now());

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  /**
   * Supprime tout ce qui se trouve après le séparateur technique --- 
   * ou les mots-clés "Phase:", "Exigence:", etc.
   */
  const cleanDisplayBotText = (text: string): string => {
    // 1. Priorité au séparateur officiel ---
    const separatorIndex = text.indexOf('---');
    if (separatorIndex !== -1) {
      return text.substring(0, separatorIndex).trim();
    }

    // 2. Sécurité : Recherche de mots-clés techniques au cas où le séparateur est oublié
    const keywords = ["Phase:", "Exigence:", "Contrôle:"];
    let firstKeywordIndex = -1;

    for (const kw of keywords) {
      const idx = text.indexOf(kw);
      if (idx !== -1 && (firstKeywordIndex === -1 || idx < firstKeywordIndex)) {
        firstKeywordIndex = idx;
      }
    }

    if (firstKeywordIndex !== -1) {
      return text.substring(0, firstKeywordIndex).trim();
    }

    return text;
  };

  const extractPhase = (text: string): number => {
    const match = text.match(/Phase:\s*(\d)/i);
    return match ? parseInt(match[1], 10) : currentPhase;
  };

  const handleExportJSON = () => {
    const data = {
      metadata: {
        student: config.studentName,
        topic: config.topic,
        mode: config.mode,
        date: new Date().toISOString()
      },
      transcript: messages,
      aiDeclaration: declarationText || ""
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Progression_${config.studentName}_${new Date().toLocaleDateString()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleSend = async (initialPrompt?: string) => {
    const text = initialPrompt || inputText;
    if (!text.trim() || !chatInstance || isLoading) return;

    const now = Date.now();
    const responseTimeMs = now - lastModelTime;
    const responseTimeSeconds = Math.max(1, Math.round(responseTimeMs / 1000));

    const charCount = text.length;
    const cpm = (charCount / responseTimeSeconds) * 60;
    const isAnomaly = !initialPrompt && charCount > 100 && cpm > 600;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: initialPrompt ? "(Démarrage de session)" : text,
      timestamp: now,
      responseTimeSeconds: initialPrompt ? 0 : responseTimeSeconds,
      hasRhythmAnomaly: isAnomaly
    };

    if (!initialPrompt) setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);
    setError(null);

    try {
      const res = await sendMessage(chatInstance, text);
      const phase = extractPhase(res.text);
      setCurrentPhase(phase);

      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: res.text,
        timestamp: Date.now(),
        phase
      };
      setMessages(prev => [...prev, aiMsg]);
      setLastModelTime(Date.now());
    } catch (e: any) {
      setError("Erreur de communication avec Argos.");
      setLastModelTime(Date.now());
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 200)}px`;
    }
  }, [inputText]);

  useEffect(() => {
    if (messages.length === 0 && chatInstance) {
      handleSend(`Bonjour Argos, je suis ${config.studentName}. Lancez la session sur : ${config.topic}.`);
    } else if (messages.length > 0) {
      const lastModelMsg = [...messages].reverse().find(m => m.role === 'model');
      if (lastModelMsg?.phase !== undefined) setCurrentPhase(lastModelMsg.phase);
    }
  }, [chatInstance]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {showGuide && <GuideModal onClose={() => setShowGuide(false)} />}

      {showDeclarationModal && (
        <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl max-w-xl w-full p-8 animate-in fade-in zoom-in duration-300">
            <h2 className="text-xl font-black flex items-center gap-3 mb-6 text-slate-900">
              <FileSignature className="text-indigo-600" /> Journal d'usage de l'IA
            </h2>
            <textarea 
              value={declarationText} 
              onChange={(e) => setDeclarationText(e.target.value)} 
              placeholder="Comment avez-vous utilisé l'IA pour vos recherches ?" 
              className="w-full h-32 p-4 bg-slate-50 border border-slate-200 rounded-xl mb-6 outline-none text-sm" 
            />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowDeclarationModal(false)} className="px-5 text-[10px] font-black uppercase text-slate-400">Retour</button>
              <button onClick={() => onFinish(declarationText || "Aucun usage déclaré.")} className="px-6 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest">Générer la trace</button>
            </div>
          </div>
        </div>
      )}

      {/* Progress tracker */}
      <div className="bg-white border-b border-slate-100 px-6 py-2 flex items-center justify-between overflow-x-auto scrollbar-hide no-print">
        <div className="flex items-center gap-2 min-w-max">
          {PROTOCOL_PHASES.map((p, i) => (
            <div key={p.id} className="flex items-center gap-2">
               <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full transition-all duration-500 ${currentPhase === p.id ? 'bg-indigo-600 text-white shadow-md' : currentPhase > p.id ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-50 text-slate-300'}`}>
                  <span className="text-[9px] font-black uppercase tracking-tighter">{i}. {p.label}</span>
                  {currentPhase > p.id && <Info size={10} />}
               </div>
               {i < PROTOCOL_PHASES.length - 1 && <ChevronRight size={12} className="text-slate-200" />}
            </div>
          ))}
        </div>
      </div>

      <header className="bg-white border-b px-6 py-4 flex justify-between items-center shrink-0 shadow-sm z-10 no-print">
        <div className="overflow-hidden flex items-center gap-4">
          <div className="hidden sm:block">
            <h2 className="text-sm font-black text-slate-900 truncate">{config.topic}</h2>
            <p className="text-[9px] text-slate-400 font-bold tracking-widest uppercase">Phase {currentPhase} : {PROTOCOL_PHASES[currentPhase]?.label}</p>
          </div>
          <button 
            onClick={handleExportJSON}
            title="Sauvegarder pour reprendre plus tard"
            className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all flex items-center gap-2 group"
          >
            <Save size={18} />
            <span className="text-[9px] font-black uppercase tracking-widest hidden md:inline">Sauvegarder</span>
          </button>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setShowGuide(true)} className="p-2 text-slate-300 hover:text-slate-600 transition-colors" title="Le projet Argos"><HelpCircle size={20} /></button>
          <button onClick={() => setShowDeclarationModal(true)} className="flex items-center gap-2 px-4 py-2 bg-rose-600 text-white rounded-xl text-[10px] font-black tracking-widest uppercase hover:bg-rose-700 transition-colors shadow-lg shadow-rose-100"><StopCircle size={14} /> Terminer la session</button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-10 scrollbar-hide">
        {messages.filter(m => !m.text.includes("Bonjour Argos")).map((msg) => (
          <div key={msg.id} className={`flex w-full animate-in fade-in slide-in-from-bottom-2 duration-300 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`group relative max-w-[88%] sm:max-w-[75%] rounded-[1.8rem] px-6 py-5 shadow-md border transition-all ${
              msg.role === 'user' 
                ? 'bg-slate-900 text-white border-slate-800 rounded-tr-none' 
                : 'bg-white text-slate-800 border-slate-200 rounded-tl-none'
            }`}>
              {msg.role === 'user' && msg.responseTimeSeconds !== undefined && msg.responseTimeSeconds > 0 && (
                <div className={`absolute -top-6 right-2 flex items-center gap-1.5 text-[8px] font-black uppercase tracking-widest ${msg.hasRhythmAnomaly ? 'text-amber-500' : 'text-slate-400'}`}>
                  <Timer size={10} />
                  Flux : {msg.responseTimeSeconds}s {msg.hasRhythmAnomaly && "• Rupture de rythme"}
                </div>
              )}
              <div className={`prose prose-sm max-w-none font-medium leading-relaxed ${
                msg.role === 'user' ? 'prose-invert prose-p:text-white prose-p:font-semibold' : 'prose-slate'
              }`}>
                <ReactMarkdown>
                  {msg.role === 'model' ? cleanDisplayBotText(msg.text) : msg.text}
                </ReactMarkdown>
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-indigo-600 text-white px-5 py-3 rounded-2xl rounded-tl-none flex items-center gap-3 animate-pulse shadow-lg shadow-indigo-200">
              <RefreshCw className="animate-spin" size={14} />
              <span className="text-[10px] font-black uppercase tracking-widest">Argos analyse votre propos...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="bg-white border-t p-4 sm:p-6 shrink-0 shadow-[0_-4px_20px_-10px_rgba(0,0,0,0.1)] no-print">
        <div className="max-w-4xl mx-auto relative group">
          <textarea 
            ref={textareaRef}
            value={inputText} 
            onChange={(e) => setInputText(e.target.value)} 
            placeholder="Répondez ici avec précision..." 
            className="w-full bg-slate-50 rounded-2xl pl-6 pr-16 py-5 border-2 border-slate-100 focus:border-indigo-500 focus:bg-white focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all text-base font-medium resize-none shadow-inner overflow-y-auto" 
            rows={1}
          />
          <button 
            onClick={() => handleSend()} 
            disabled={!inputText.trim() || isLoading} 
            className="absolute right-3 bottom-3 p-3 bg-slate-900 text-white rounded-xl disabled:opacity-10 hover:bg-indigo-600 transition-all shadow-lg active:scale-90"
            title="Envoyer le message"
          >
            <Send size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_CHAT = "gemini-3-flash-preview";
const MODEL_ANALYSIS = "gemini-3-pro-preview";
const TUTOR_NAME = "ARGOS";

const CORE_RULES = `
Identité et mission :
- Tu es ${TUTOR_NAME}, un "taon" socratique (l'insecte qui pique pour réveiller la pensée).
- Ton rôle n'est pas d'être utile, agréable ou pédagogique au sens classique, mais d'être un obstacle fertile.

Règles de fer (DURCISSEMENT) :
1. INTERDICTION DE FLATTERIE : Ne dis JAMAIS "C'est une excellente analyse", "Je suis d'accord" ou "Bravo". La validation tue la réflexion. Reste froidement analytique.
2. DÉTECTION DES ESQUIVES : Si l'apprenant·e te pose une question pour éviter de répondre à la tienne, pointe explicitement cette stratégie de fuite. Dis : "Vous déplacez le questionnement pour éviter l'effort de définition. Revenons à..."
3. REFUS DE RÉPONDRE : Ne réponds pas aux questions factuelles ou techniques si elles servent à l'apprenant·e à se reposer sur toi. Ton rôle est de lui demander : "Que croyez-vous savoir sur ce point ?"
4. RIGUEUR DE PHASE : Ne passe jamais à la technique (Phase 2+) tant que les concepts de base (Phase 1) ne sont pas définis avec une précision chirurgicale. Si l'apprenant·e veut aller trop vite, ramène-le aux fondations.

Pilotage invisible : À la toute fin de ton message, ajoute obligatoirement le marqueur de phase sous cette forme exacte, précédé de trois tirets :
---
Phase: [Numéro]
`.trim();

const TUTOR_INSTRUCTIONS = `
${CORE_RULES}

Mode : Tuteur (Le Taon Socratique)
- Ta mission : Déstabiliser les certitudes de l'apprenant·e.
- Méthode : Utilise l'elenchos (la réfutation). Pousse l'apprenant·e dans ses propres contradictions jusqu'à ce qu'il/elle admette qu'il/elle ne sait pas (l'aporie).
- Posture : Austère, neutre, intellectuellement implacable.
`.trim();

const CRITIC_INSTRUCTIONS = `
${CORE_RULES}

Mode : Critique (L'Audit Corrosif)
- Ta mission : Présenter des raisonnements séduisants mais viciés.
- Méthode : Ton premier message contient un "sophisme élégant" lié au sujet. Défends-le avec arrogance si nécessaire.
- Ton but : Voir si l'apprenant·e a le courage intellectuel de te contredire avec des preuves solides.
- Posture : Un avocat du diable sophistiqué et légèrement provocateur.
`.trim();

export const createChatSession = (mode: SocraticMode, topic: string, history: Message[] = []): Chat => {
  const systemInstruction = mode === SocraticMode.TUTOR 
    ? `${TUTOR_INSTRUCTIONS}\n\nSujet d'exploration : "${topic}".`
    : `${CRITIC_INSTRUCTIONS}\n\nSujet d'exploration : "${topic}".`;

  return ai.chats.create({
    model: MODEL_CHAT,
    config: {
      systemInstruction,
      temperature: 0.7, // Réduit légèrement pour plus de cohérence logique
      thinkingConfig: { thinkingBudget: 2048 }
    },
    history: history.map(m => ({
      role: m.role,
      parts: [{ text: m.text }]
    }))
  });
};

export const sendMessage = async (chat: Chat, message: string) => {
  const response = await chat.sendMessage({ message });
  return { text: response.text || "Oups, petit souci technique." };
};

export const generateAnalysis = async (
  transcript: Message[],
  topic: string,
  aiDeclaration: string
): Promise<AnalysisData> => {
  const transcriptWithTiming = transcript.map(m => {
    const timing = m.role === 'user' ? ` [Temps de saisie: ${m.responseTimeSeconds}s]` : '';
    return `[${m.role === "user" ? "Apprenant·e" : TUTOR_NAME}]: ${m.text}${timing}`;
  }).join("\n");

  const prompt = `
Analyse cette discussion sur "${topic}".

Déclaration d'usage IA de l'apprenant·e :
"${aiDeclaration}"

Ta mission :
Évalue si l'apprenant·e a réellement progressé ou s'il/elle a simplement "subi" le dialogue.
Vérifie particulièrement les moments où Argos a pointé une esquive et comment l'apprenant·e a réagi.

Transcription :
${transcriptWithTiming}

Instructions de sortie (JSON) :
- summary: Bilan de la progression cognitive (150 mots max).
- rhythmBreakCount: Le nombre de réponses utilisateur présentant une rupture de rythme.
- integrityScore: Reflet de la cohérence entre la déclaration et le travail observé (0 à 100).
`.trim();

  const response = await ai.models.generateContent({
    model: MODEL_ANALYSIS,
